-- Inventory-only update: add optional sickness field and populate the requested catalog.
-- Product pack/volume sizes are intentionally not stored by this migration.
SET @inventory_sickness_exists := (
    SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'inventory_items' AND COLUMN_NAME = 'sickness'
);
SET @inventory_sickness_sql := IF(@inventory_sickness_exists = 0,
    'ALTER TABLE `inventory_items` ADD COLUMN `sickness` TEXT NULL AFTER `category`',
    'SELECT 1'
);
PREPARE inventory_sickness_stmt FROM @inventory_sickness_sql;
EXECUTE inventory_sickness_stmt;
DEALLOCATE PREPARE inventory_sickness_stmt;

